import numpy as np,itertools
L=open('ff3.xyz').read().split('\n')[2:]
A=[(l.split()[0],np.array(l.split()[1:4],float)) for l in L if l.strip()]
r={'H':0.32,'C':0.76,'N':0.71,'Ga':1.3,'Ni':1.3}
for i,(e,p) in enumerate(A):
  nb=[A[j][0]+str(j)+':%.2f'%np.linalg.norm(p-q) for j,(f,q) in enumerate(A) if j!=i and np.linalg.norm(p-q)<1.2*(r[e]+r[f])]
  print(i,e,len(nb),nb)
for i,j in itertools.combinations(range(len(A)),2):
  d=np.linalg.norm(A[i][1]-A[j][1])
